const item = $input.item.json;
const densityRows = (item.densityRows || []).slice(1); // skip header
const incidentRows = (item.incidentRows || []).slice(1); // skip header

// Density columns: [zoneId, zoneName, currentOccupancy, capacity, location, lastUpdated]
// Incident columns: [reportId, zoneId, incidentType, severity, description, reportedAt, status]

const severityWeight = { Low: 10, Medium: 25, High: 45, Critical: 70 };

const zones = densityRows.map(r => {
  const zoneId = r[0] || '';
  const zoneName = r[1] || '';
  const currentOccupancy = parseInt(r[2], 10) || 0;
  const capacity = parseInt(r[3], 10) || 1;
  const location = r[4] || '';
  const lastUpdated = r[5] || '';

  const zoneIncidents = incidentRows.filter(i => i[1] === zoneId && (i[6] || '').toLowerCase() === 'open');
  const incidentCount = zoneIncidents.length;
  const incidentScore = Math.min(100, zoneIncidents.reduce((sum, i) => sum + (severityWeight[i[3]] || 15), 0));

  const occupancyRate = capacity > 0 ? Math.round((currentOccupancy / capacity) * 100) : 0;
  const occupancyScore = Math.min(100, occupancyRate);
  const riskScore = Math.round(occupancyScore * 0.6 + incidentScore * 0.4);

  let riskLevel = 'Low';
  if (riskScore >= 85) riskLevel = 'Critical';
  else if (riskScore >= 65) riskLevel = 'High';
  else if (riskScore >= 40) riskLevel = 'Medium';

  return {
    zoneId, zoneName, currentOccupancy, capacity, location, lastUpdated,
    occupancyRate, incidentCount,
    incidentSummary: zoneIncidents.map(i => `${i[2]} (${i[3]})`).join('; '),
    riskScore, riskLevel
  };
});

// Attach nearby lower-risk zones as reroute candidates
zones.forEach(z => {
  z.nearbyLowRiskZones = zones
    .filter(o => o.zoneId !== z.zoneId && o.riskScore < 40)
    .sort((a, b) => a.occupancyRate - b.occupancyRate)
    .slice(0, 3)
    .map(o => `${o.zoneName} (${o.occupancyRate}% full)`);
});

return { json: { zones, checkedAt: new Date().toISOString() } };

const item = $input.item.json;
const loggedAt = new Date().toISOString();

return {
  json: {
    ...item,
    loggedAt,
    heatmapSummaryRow: [
      loggedAt,
      item.zoneId || '',
      item.zoneName || '',
      item.currentOccupancy || 0,
      item.capacity || 0,
      (item.occupancyRate || 0) + '%',
      item.incidentCount || 0,
      item.riskScore || 0,
      item.riskLevel || '',
      item.location || ''
    ]
  }
};

parameters.text:
=You are a real-time crowd safety coordinator.

Zone: {{ $json.zoneName }} ({{ $json.zoneId }})
Location: {{ $json.location }}
Current Occupancy: {{ $json.currentOccupancy }} / {{ $json.capacity }} ({{ $json.occupancyRate }}% full)
Active Incidents: {{ $json.incidentSummary || 'None reported' }}
Risk Level: {{ $json.riskLevel }} ({{ $json.riskScore }}/100)
Nearby Lower-Risk Zones: {{ JSON.stringify($json.nearbyLowRiskZones) }}

Write short, calm, actionable guidance for travelers currently near or heading toward this zone. Suggest a specific reroute using one of the nearby lower-risk zones if any are available, and give one practical safety tip suited to the risk level.

Return a JSON object with EXACTLY these fields:
{
  "alertHeadline": "Under 10 words, urgent but calm",
  "rerouteMessage": "Under 200 characters, suitable for SMS, names a specific alternate zone if one is available",
  "safetyTip": "One short, practical safety tip"
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  const alt = (item.nearbyLowRiskZones && item.nearbyLowRiskZones[0]) || 'a nearby area';
  parsed = {
    alertHeadline: `${item.riskLevel} crowd risk at ${item.zoneName}`,
    rerouteMessage: `${item.zoneName} is currently at ${item.occupancyRate}% capacity with ${item.riskLevel.toLowerCase()} risk. Consider heading toward ${alt} instead.`,
    safetyTip: 'Stay aware of exits and follow any on-site staff instructions.'
  };
}
return {
  json: {
    ...item,
    ...parsed
  }
};

const item = $input.item.json;
const rows = (item.values || []).slice(1); // [subscriberId, name, phone, zoneId, status]

const travelers = rows
  .filter(r => (r[4] || '').toLowerCase() === 'active' && (r[3] === item.zoneId || (r[3] || '').toLowerCase() === 'all'))
  .map(r => ({ subscriberId: r[0] || '', name: r[1] || '', phone: r[2] || '' }));

return {
  json: {
    ...item,
    travelers,
    travelerCount: travelers.length
  }
};
